class Solution {
public:
    vector<int> decrypt(vector<int>& code, int k) {
        int n = code.size();
        vector<int> res(n, 0);
        if (k == 0) return res;

        if (k > 0) {
            int sum = 0;
            for (int i = 1; i <= k; i++) {
                sum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                res[i] = sum;
                sum = sum - code[(i + 1) % n] + code[(i + 1 + k) % n];
            }
        } else {
            int m = -k;
            int sum = 0;
            for (int i = n - m; i < n; i++) {
                sum += code[i];
            }
            for (int i = 0; i < n; i++) {
                res[i] = sum;
                sum = sum - code[(i - m + n) % n] + code[i];
            }
        }

        return res;
    }
};
